// mockCtgov is an in-memory ctgovClient for exercising the ClinicalTrials.gov
// aggregation path (ctgovCount + ctgovFetch + counter) without a live API. It
// serves a fixed total for count queries and a fixed study set for fetches, and
// records the query.intr term it was asked for so tests can assert on it.
type mockCtgov struct {
	total       int
	studies     []json.RawMessage
	lastIntr    string
	lastCounted bool
}

func (m *mockCtgov) Get(_ context.Context, path string, params map[string]string) (json.RawMessage, error) {
	if v, ok := params["query.intr"]; ok {
		m.lastIntr = v
	}
	if params["countTotal"] == "true" {
		m.lastCounted = true
		return json.Marshal(map[string]any{"totalCount": m.total})
	}
	return json.Marshal(map[string]any{"studies": m.studies})
}

// studyJSON builds a minimal CT.gov study object matching the fields
// normalizeStudy reads, so mock fetches flatten into real Trial values.
func studyJSON(nct, status, phase, sponsor, sponsorClass string) json.RawMessage {
	s := map[string]any{
		"protocolSection": map[string]any{
			"identificationModule":       map[string]any{"nctId": nct, "briefTitle": "Trial " + nct},
			"statusModule":               map[string]any{"overallStatus": status},
			"sponsorCollaboratorsModule": map[string]any{"leadSponsor": map[string]any{"name": sponsor, "class": sponsorClass}},
			"designModule":               map[string]any{"phases": []string{phase}},
		},
	}
	b, _ := json.Marshal(s)
	return b
}

