// TestCompareAggregation exercises the ClinicalTrials.gov side of compare
// against a mock client: ctgovCount must read the total, ctgovFetch must
// normalize the studies, and the phase/sponsor counters compare uses must
// aggregate them correctly.
func TestCompareAggregation(t *testing.T) {
	ctx := context.Background()
	mock := &mockCtgov{
		total: 42,
		studies: []json.RawMessage{
			studyJSON("NCT1", "RECRUITING", "PHASE3", "Pfizer", "INDUSTRY"),
			studyJSON("NCT2", "RECRUITING", "PHASE3", "Pfizer", "INDUSTRY"),
			studyJSON("NCT3", "COMPLETED", "PHASE2", "NIH", "NIH"),
		},
	}

	// Count path.
	total, err := ctgovCount(ctx, mock, ctgovParams("intr", "Keytruda OR pembrolizumab"))
	if err != nil {
		t.Fatalf("ctgovCount: %v", err)
	}
	if total != 42 {
		t.Errorf("total = %d, want 42", total)
	}
	if !mock.lastCounted {
		t.Error("expected ctgovCount to issue a countTotal query")
	}
	if mock.lastIntr != "Keytruda OR pembrolizumab" {
		t.Errorf("query.intr = %q, want %q", mock.lastIntr, "Keytruda OR pembrolizumab")
	}

	// Fetch + aggregate path (mirrors buildDrugProfile's counters).
	trials, err := ctgovFetch(ctx, mock, ctgovParams("intr", "Keytruda"), 100, 1)
	if err != nil {
		t.Fatalf("ctgovFetch: %v", err)
	}
	if len(trials) != 3 {
		t.Fatalf("fetched %d trials, want 3", len(trials))
	}
	phase := newCounter()
	sponsor := newCounter()
	for _, tr := range trials {
		for _, ph := range tr.Phases {
			phase.add(phaseLabel(ph))
		}
		sponsor.add(tr.Sponsor)
	}
	phaseTop := phase.top(8)
	if len(phaseTop) == 0 || phaseTop[0].Label != "Phase 3" || phaseTop[0].Count != 2 {
		t.Errorf("top phase = %+v, want Phase 3 x2", phaseTop)
	}
	sponsorTop := sponsor.top(8)
	if len(sponsorTop) == 0 || sponsorTop[0].Label != "Pfizer" || sponsorTop[0].Count != 2 {
		t.Errorf("top sponsor = %+v, want Pfizer x2", sponsorTop)
	}
}
